use std::collections::VecDeque;

// Two independent limits:
//   prefetch        -> how many unacked messages the broker will hand over.
//   local_capacity  -> how much in-process work the consumer will buffer.
// A generous prefetch without a local cap just moves the pile-up into the heap.
struct Consumer {
    prefetch: usize,
    in_flight: usize,       // unacked messages held (<= prefetch)
    local: VecDeque<u32>,   // bounded in-process work buffer
    local_capacity: usize,
    rejected: usize,        // work shed because the local buffer was full
    done: usize,
}

impl Consumer {
    fn new(prefetch: usize, local_capacity: usize) -> Self {
        Consumer {
            prefetch,
            in_flight: 0,
            local: VecDeque::new(),
            local_capacity,
            rejected: 0,
            done: 0,
        }
    }

    // The broker offers a message: honor prefetch first, then the local cap.
    fn offer(&mut self, msg: u32) {
        if self.in_flight >= self.prefetch {
            return; // broker-side backpressure: it would not hand over more
        }
        self.in_flight += 1;
        if self.local.len() >= self.local_capacity {
            // local backpressure: shed load explicitly instead of growing the heap
            self.rejected += 1;
            self.in_flight -= 1;
            return;
        }
        self.local.push_back(msg);
    }

    // A worker drains one message, does the work, and acks (freeing prefetch).
    fn work_once(&mut self) {
        if self.local.pop_front().is_some() {
            self.done += 1;
            self.in_flight -= 1;
        }
    }
}

fn main() {
    // prefetch is generous (8) but the local worker buffer holds only 2.
    let mut c = Consumer::new(8, 2);

    // The broker offers 5 messages in a burst before any worker runs.
    for msg in 1..=5 {
        c.offer(msg);
    }

    // Prefetch alone would admit all 5; the local cap of 2 is what protects
    // the process, shedding the other 3.
    println!("buffered = {}", c.local.len()); // 2
    println!("rejected = {}", c.rejected);    // 3

    c.work_once();
    c.work_once();
    println!("done = {}", c.done);            // 2
}

